def predecir_valor(sepal length (cm), sepal width (cm), petal length (cm), petal width (cm)):
    """
    Función generada automáticamente que implementa el árbol de decisión entrenado.

    Parameters:
    	sepal length (cm): float - sepal length (cm)
	sepal width (cm): float - sepal width (cm)
	petal length (cm): float - petal length (cm)
	petal width (cm): float - petal width (cm)

    Returns:
        float - El valor predicho

    Árbol entrenado para regresión con 4 características.
    Profundidad máxima: 3
    Número de nodos: 9
    """
if petal length (cm) <= 2.450000:
    return 0.000000
else:
    if petal length (cm) <= 4.750000:
        if petal width (cm) <= 1.600000:
            return 1.000000
        else:
            return 2.000000
    else:
        if petal width (cm) <= 1.750000:
            return 1.500000
        else:
            return 1.969697

